#include <stdio.h>
#include <stdint.h>
typedef unsigned char * PCRE2_SPTR;
typedef size_t PCRE2_SIZE;
typedef unsigned char PCRE2_UCHAR;
typedef struct heapframe {
  PCRE2_SPTR ecode;
  PCRE2_SPTR temp_sptr[2];
  PCRE2_SIZE length;
  PCRE2_SIZE back_frame;
  PCRE2_SIZE temp_size;
  uint32_t rdepth;
  uint32_t group_frame_type;
  uint32_t temp_32[4];
  uint16_t return_id;
  uint16_t op;
  PCRE2_UCHAR occu[6];
  PCRE2_SPTR eptr;
  PCRE2_SPTR start_match;
  PCRE2_SPTR mark;
  uint32_t current_recurse;
  uint32_t capture_last;
  PCRE2_SIZE last_group_offset;
  PCRE2_SIZE offset_top;
  PCRE2_SIZE ovector[2];
} heapframe;
int main(){printf("sizeof=%zu off_ovector=%zu off_eptr=%zu\n",sizeof(heapframe), __builtin_offsetof(heapframe, ovector), __builtin_offsetof(heapframe, eptr)); for(int t=0;t<32;t++){size_t fs=sizeof(heapframe)+((t-1)*2*sizeof(size_t)); printf("top %d frame %zu cap %zu read %zu\n",t,fs,10240/fs, (size_t)62*8);} }
EOF
typedef struct heapframe {

  /* The first set of fields are variables that have to be preserved over calls
  to RRMATCH(), but which do not need to be copied to new frames. */

  PCRE2_SPTR ecode;          /* The current position in the pattern */
  PCRE2_SPTR temp_sptr[2];   /* Used for short-term PCRE_SPTR values */
  PCRE2_SIZE length;         /* Used for character, string, or code lengths */
  PCRE2_SIZE back_frame;     /* Amount to subtract on RRETURN */
  PCRE2_SIZE temp_size;      /* Used for short-term PCRE2_SIZE values */
  uint32_t rdepth;           /* "Recursion" depth */
  uint32_t group_frame_type; /* Type information for group frames */
  uint32_t temp_32[4];       /* Used for short-term 32-bit or BOOL values */
  uint16_t return_id;        /* Where to go on in internal "return" */
  uint16_t op;               /* Processing opcode */

#if PCRE2_CODE_UNIT_WIDTH == 8
  PCRE2_UCHAR occu[6];       /* Used for other case code units */
#elif PCRE2_CODE_UNIT_WIDTH == 16
  PCRE2_UCHAR occu[2];       /* Used for other case code units */
#else
  PCRE2_UCHAR occu[1];       /* Used for other case code units */
#endif

  /* The rest have to be copied from the previous frame whenever a new frame
  becomes current. */

  PCRE2_SPTR eptr;           /* MUST BE FIRST */
  PCRE2_SPTR start_match;    /* Can be adjusted by \K */
  PCRE2_SPTR mark;           /* Most recent mark on the success path */
  uint32_t current_recurse;  /* Current (deepest) recursion number */
  uint32_t capture_last;     /* Most recent capture */
  PCRE2_SIZE last_group_offset;  /* Saved offset to most recent group frame */
  PCRE2_SIZE offset_top;     /* Offset after highest capture */
  PCRE2_SIZE ovector[2];     /* Must be last in the structure */
} heapframe;


